package expo.modules.liquidglass.menumotion

import android.graphics.RectF
import kotlin.math.abs
import kotlin.math.max

/** Golden values were generated by compiling unmodified upstream GlassJelly
 * and GlassSpring at 0021efd8ab0d068f155bbdac62c5f673ccc39a24. They check the
 * original default response, rather than merely repeating our port's formula. */
fun main() {
  var checks = 0
  fun verify(value: Boolean, message: String) { checks++; check(value) { message } }
  fun near(a: Float, b: Float, message: String, tolerance: Float = .003f) =
    verify(abs(a - b) <= tolerance, "$message: $a != $b")
  fun rectNear(a: RectF, b: RectF, message: String, tolerance: Float = .003f) {
    near(a.left, b.left, "$message left", tolerance); near(a.top, b.top, "$message top", tolerance)
    near(a.right, b.right, "$message right", tolerance); near(a.bottom, b.bottom, "$message bottom", tolerance)
  }
  val base = RectF(210f, 400f, 1380f, 2800f)
  fun live(jelly: GlassJelly, awayX: Float = -1f, awayY: Float = 1f, amount: Float = 1f) = RectF().also {
    it.set(base); jelly.deformMenu(it, awayX, awayY, 3.75f, amount)
  }
  val jelly = GlassJelly()
  jelly.down(500f, 200f)
  repeat(18) { jelly.advance(1f / 120f) }
  rectNear(live(jelly), base, "A stationary hold must not invent a drag deformation")
  near(jelly.glowValue, .9991587f, "Original GlowIn response")
  near(jelly.swell(2400f, 3.75f, 1f), 1.0055487f, "Original 4dp control press lift", .00001f)
  near(jelly.lightPositionX, 500f, "Initial touch light X")
  near(jelly.lightPositionY, 200f, "Initial touch light Y")

  jelly.move(680f, 580f)
  repeat(6) { jelly.advance(1f / 120f) }
  rectNear(live(jelly), RectF(232.93481f, 407.44617f, 1376.026f, 2831.9253f), "Original 50ms DragFollow")
  near(jelly.lightPositionX, 619.5873f, "Original light follow X")
  near(jelly.lightPositionY, 452.46204f, "Original light follow Y")
  repeat(18) { jelly.advance(1f / 120f) }
  rectNear(live(jelly), RectF(244.51807f, 410.9203f, 1374.2782f, 2847.6191f), "Original 200ms drag overshoot")
  jelly.move(360f, 40f)
  repeat(12) { jelly.advance(1f / 120f) }
  val beforeRelease = live(jelly)
  rectNear(beforeRelease, RectF(185.27148f, 397.00378f, 1379.7302f, 2773.125f), "Original reverse drag")
  jelly.release()
  rectNear(live(jelly), beforeRelease, "Release/cancel must preserve instantaneous deformation")
  repeat(6) { jelly.advance(1f / 120f) }
  rectNear(live(jelly), RectF(185.76562f, 396.57056f, 1380.1819f, 2772.9226f), "Original release recoil")
  near(jelly.glowValue, .8686887f, "Original GlowOut response")
  repeat(30) { jelly.advance(1f / 120f) }
  rectNear(live(jelly), RectF(214.14838f, 400.58057f, 1379.9749f, 2804.6252f), "Original 300ms release overshoot")
  verify(!jelly.isSettled, "A release must retain its physical tail until the springs settle")
  repeat(300) { jelly.advance(1f / 120f) }
  rectNear(live(jelly), base, "Released/cancelled jelly must return exactly to rest")
  near(jelly.glowValue, 0f, "Released light must not remain visible")
  verify(jelly.isSettled, "Released jelly must stop requesting frames")

  // Same gestures at several real display cadences must remain bounded and
  // return to rest. Direction changes affect stretch/squash, not light coords.
  for (hz in listOf(24, 60, 90, 120, 144)) {
    for (awayX in listOf(-1f, 1f)) for (awayY in listOf(-1f, 1f)) {
      val interaction = GlassJelly()
      interaction.down(500f, 200f)
      interaction.move(50000f, -50000f)
      repeat(hz) {
        interaction.advance(1f / hz)
        val shown = live(interaction, awayX, awayY)
        verify(shown.width() > 0f && shown.height() > 0f, "Extreme drag inverted the menu")
        verify(listOf(shown.left, shown.top, shown.right, shown.bottom).all(Float::isFinite), "Extreme drag produced nonfinite geometry")
        verify(abs(shown.centerX() - base.centerX()) <= 21f * 3.75f + .01f &&
          abs(shown.centerY() - base.centerY()) <= 21f * 3.75f + .01f, "Drag exceeded upstream 21dp center limit")
        verify(abs(shown.width() - base.width()) <= 37f * 3.75f + .01f &&
          abs(shown.height() - base.height()) <= 37f * 3.75f + .01f, "Drag exceeded upstream stretch/squash bounds")
        rectNear(live(interaction, awayX, awayY, 0f), base, "Zero jelly amount must preserve the resting recipe")
      }
      interaction.release() // ACTION_CANCEL uses the same release response.
      repeat(hz * 5) { interaction.advance(1f / hz) }
      verify(interaction.isSettled, "Cancel leaked frame requests at $hz Hz")
      rectNear(live(interaction, awayX, awayY), base, "Cancel left a permanent warped menu")
    }
  }

  // Closing a pressed menu must retarget its morph while retaining the jelly
  // state. Clearing the jelly here would visibly snap just before absorption.
  val source = RectF(1240f, 140f, 1380f, 280f)
  val motion = GlassMotion()
  motion.initialize(source, base, 105f, 3.75f, source, false, GlassMorphTuning(null, null))
  motion.retarget(true)
  repeat(240) { motion.advanceBy(1f / 120f) }
  val unchangedPhysics = RectF().also { it.set(motion.frame.bounds) }
  val presentation = GlassMorphFrame().also { it.copyFrom(motion.frame) }
  val pressed = GlassJelly()
  pressed.down(600f, 700f); pressed.move(750f, 1000f)
  repeat(18) { pressed.advance(1f / 120f) }
  pressed.deformMenu(presentation.bounds, -1f, 1f, 3.75f, 1f)
  rectNear(motion.frame.bounds, unchangedPhysics, "Presentation jelly must not mutate underlying morph springs")
  verify(abs(presentation.bounds.centerX() - unchangedPhysics.centerX()) > 1f,
    "The copy regression never exercised a visible deformation")
  near(presentation.rowsOpacity, motion.frame.rowsOpacity, "Jelly copy changed foreground reveal")
  near(presentation.sourceZoom, motion.frame.sourceZoom, "Jelly copy changed source rebound zoom")
  rectNear(presentation.sourceLobe, motion.frame.sourceLobe, "Jelly copy changed the plain trigger's source lobe")
  fun shown() = RectF().also { it.set(motion.frame.bounds); pressed.deformMenu(it, -1f, 1f, 3.75f, 1f) }
  val beforeClose = shown()
  pressed.release()
  motion.retarget(false)
  rectNear(shown(), beforeClose, "Selection close cleared the live deformation instead of absorbing it")
  var previous = shown()
  var peakDelta = 0f
  repeat(240) {
    motion.advanceBy(1f / 120f); pressed.advance(1f / 120f)
    val current = shown()
    peakDelta = max(peakDelta, max(abs(current.centerX() - previous.centerX()), abs(current.centerY() - previous.centerY())))
    verify(current.width() > 0f && current.height() > 0f, "Pressed absorption invalidated its contour")
    previous = current
  }
  verify(pressed.isSettled && motion.frame.rowsOpacity == 0f, "Pressed absorption retained rows or a live jelly tail")
  verify(peakDelta < base.height() / 8f, "Pressed absorption contained a discontinuous one-frame reset")

  val rows = listOf(
    MenuInteractionRow("first", RectF(8f, 10f, 242f, 52f)),
    MenuInteractionRow("disabled", RectF(8f, 52f, 242f, 94f), enabled = false),
    MenuInteractionRow("last", RectF(8f, 94f, 242f, 152f), keepOpen = true),
  )
  val selector = MenuInteractionMotion(1f)
  selector.setRows(rows)
  verify(!selector.down(20f, 70f), "A disabled row began a native selection gesture")
  verify(selector.down(20f, 20f), "Enabled row did not begin a native selection gesture")
  selector.updatePlate(250f)
  rectNear(selector.plateRect, RectF(8f, 10f, 242f, 52f), "DOWN must immediately place the selected plate")
  near(selector.plateAlpha, 1f, "DOWN plate must be immediately visible")
  selector.move(20f, 110f)
  selector.updatePlate(250f)
  rectNear(selector.plateRect, RectF(8f, 10f, 242f, 52f), "MOVE must spring the plate rather than teleport it")
  repeat(6) { selector.advance(1f / 120f) }
  selector.updatePlate(250f)
  verify(selector.plateRect.top > 10f && selector.plateRect.top < 94f,
    "Selection plate did not interpolate between registered rows")
  verify(selector.plateRect.height() > 42f && selector.plateRect.height() < 58f,
    "Selection plate height did not interpolate to the subtitle/taller row")
  verify(selector.rowChanges == 1, "Moving across one enabled row generated duplicate haptic transitions")
  selector.move(25f, 115f)
  verify(selector.rowChanges == 1, "Moving within the same row generated duplicate haptic transitions")
  val selected = selector.up(25f, 115f)
  verify(selected?.id == "last" && selected.keepOpen, "UP did not activate the exact enabled row/keepOpen metadata")
  verify(selector.up(25f, 115f) == null, "One gesture activated its row twice")
  verify(selector.plateAlpha > .99f, "Selection release reset the visible plate before its fade spring")
  repeat(600) { selector.advance(1f / 120f) }
  verify(selector.isSettled && selector.plateAlpha == 0f && selector.glowValue == 0f,
    "Selection close retained its plate/light or leaked frame requests")

  // Scrub slack keeps feedback alive outside the exact actionable row, but it
  // must never turn an out-of-bounds finger release into an action.
  selector.down(20f, 20f)
  selector.move(-10f, 20f)
  repeat(18) { selector.advance(1f / 120f) }
  near(selector.plateAlpha, 1f, "24dp outside scrub slack should retain hover feedback")
  verify(selector.up(-10f, 20f) == null, "Hover slack incorrectly activated an outside UP")
  selector.down(20f, 20f)
  selector.move(-30f, 20f)
  repeat(120) { selector.advance(1f / 120f) }
  near(selector.plateAlpha, 0f, "Moving beyond scrub slack must clear hover feedback")
  verify(selector.up(20f, 70f) == null, "Releasing on a disabled row activated an action")

  selector.down(20f, 20f)
  selector.move(20f, 110f)
  selector.cancel()
  verify(selector.up(20f, 110f) == null, "CANCEL later activated a stale candidate")
  repeat(600) { selector.advance(1f / 120f) }
  verify(selector.isSettled && selector.plateAlpha == 0f, "CANCEL retained an active plate")
  selector.down(20f, 20f)
  selector.move(20f, 110f)
  selector.cancelForScroll()
  verify(selector.up(20f, 110f) == null, "A parent-owned scroll later activated an option")
  repeat(600) { selector.advance(1f / 120f) }
  verify(selector.isSettled && selector.glowValue == 0f, "Scroll end leaked the held glow")

  // A finger can stay DOWN after its light/plate springs have settled. The
  // native host must retain one raster epoch for this live gesture, while the
  // settled springs themselves permit the frame loop to sleep until MOVE/UP.
  val held = MenuInteractionMotion(1f)
  held.setRows(rows)
  held.down(20f, 20f)
  repeat(1200) { held.advance(1f / 120f) }
  verify(held.isSettled, "A stationary hold would force unnecessary continuous frame requests")
  verify(held.isPressed, "Settled DOWN must retain its active resource epoch")
  near(held.glowValue, 1f, "Settled DOWN must retain the original held light")
  near(held.plateAlpha, 1f, "Settled DOWN must retain its selection feedback")
  verify(held.up(20f, 20f)?.id == "first", "Settling while DOWN disposed the still-active gesture")
  verify(!held.isPressed, "Terminal UP failed to release its held resource epoch")
  held.down(20f, 20f)
  repeat(1200) { held.advance(1f / 120f) }
  held.cancel()
  verify(!held.isPressed, "CANCEL failed to release a settled held resource epoch")
  verify(held.up(20f, 20f) == null, "A cancelled long hold later selected an option")

  // Geometric feedback must not change the menu model's registered row bounds.
  rectNear(rows[0].rect, RectF(8f, 10f, 242f, 52f), "Interaction mutated registered first-row geometry")
  rectNear(rows[2].rect, RectF(8f, 94f, 242f, 152f), "Interaction mutated registered last-row geometry")

  // SpeedSheet is a two-dimensional grid. Its pressed plate must follow the
  // actual registered cell on both axes; the original vertical-menu nearest-Y
  // shortcut cannot be reused for these three-column finite options.
  val gridRows = listOf(
    MenuInteractionRow("g1", RectF(8f, 10f, 80f, 52f), fullWidth = false),
    MenuInteractionRow("g2-disabled", RectF(88f, 10f, 160f, 52f), enabled = false, fullWidth = false),
    MenuInteractionRow("g3", RectF(168f, 10f, 240f, 52f), fullWidth = false),
    MenuInteractionRow("g4", RectF(8f, 76f, 80f, 118f), fullWidth = false),
    MenuInteractionRow("g5", RectF(88f, 76f, 160f, 118f), fullWidth = false),
    MenuInteractionRow("g6", RectF(168f, 76f, 240f, 118f), fullWidth = false),
  )
  val grid = MenuInteractionMotion(1f)
  grid.setRows(gridRows)
  val initialRightCell = MenuInteractionMotion(1f)
  initialRightCell.setRows(gridRows)
  verify(initialRightCell.down(190f, 20f), "A fresh right-hand grid cell failed its first DOWN")
  initialRightCell.updatePlate(250f)
  rectNear(initialRightCell.plateRect, gridRows[2].rect,
    "A fresh grid controller needs the actual right-cell origin before its first drawn plate")
  verify(!grid.down(110f, 20f), "A disabled grid cell began a selection gesture")
  verify(grid.down(20f, 20f), "Enabled grid cell failed to begin a gesture")
  grid.updatePlate(250f)
  rectNear(grid.plateRect, gridRows[0].rect, "Grid DOWN plate must match its actual cell, not menu width")
  grid.move(190f, 20f)
  grid.updatePlate(250f)
  rectNear(grid.plateRect, gridRows[0].rect, "Same-row horizontal scrub must animate rather than teleport")
  repeat(120) { grid.advance(1f / 120f) }
  grid.updatePlate(250f)
  rectNear(grid.plateRect, gridRows[2].rect, "Same-Y scrub failed to choose the actual right-hand cell")
  grid.move(190f, 90f)
  repeat(120) { grid.advance(1f / 120f) }
  grid.updatePlate(250f)
  rectNear(grid.plateRect, gridRows[5].rect, "Diagonal scrub ignored the actual grid column")
  verify(grid.up(190f, 90f)?.id == "g6", "Grid UP did not choose the exact row/column")
  verify(grid.up(190f, 90f) == null, "Grid UP delivered one gesture twice")
  grid.down(190f, 20f)
  grid.move(252f, 20f) // Inside 24dp hover slack beyond right-most exact cell.
  repeat(120) { grid.advance(1f / 120f) }
  grid.updatePlate(250f)
  rectNear(grid.plateRect, gridRows[2].rect, "Two-dimensional outside hover chose another column")
  verify(grid.up(252f, 20f) == null, "Grid hover slack activated an out-of-bounds UP")
  grid.down(190f, 20f)
  grid.move(20f, 90f)
  grid.cancel()
  verify(grid.up(20f, 90f) == null, "Cancelled diagonal grid gesture activated a stale cell")
  repeat(600) { grid.advance(1f / 120f) }
  verify(grid.isSettled && grid.plateAlpha == 0f && grid.glowValue == 0f,
    "Cancelled grid gesture retained light, plate or frame requests")
  println("Jelly interaction harness passed: $checks checks; upstream numeric goldens, hold/drag/release/cancel, direction/bounds/cadence, continuous absorption and finite-row scrub selection.")
}
